/*
  onboarding.css
  Holds keyframes, interactive pseudo-classes, toggle-switch knob, and responsive breakpoints.
*/

/* ---------- keyframes ---------- */

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes shimmer {
  0% {
    background-position: 260% 0;
  }
  100% {
    background-position: -260% 0;
  }
}

@keyframes scanPulse {
  0% {
    transform: scale(0.65);
    opacity: 0.55;
  }
  100% {
    transform: scale(1.35);
    opacity: 0;
  }
}

@keyframes swatchPop {
  0% {
    transform: scale(1);
  }
  40% {
    transform: scale(1.08);
  }
  100% {
    transform: scale(1);
  }
}

/* ---------- animated classes ---------- */

.spinner {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 3px solid #e3e3e3;
  border-top-color: #008060;
  animation: spin 0.75s linear infinite !important;
  flex-shrink: 0;
}

.processing-text {
  font-size: clamp(1.25rem, 3.2vw, 1.75rem);
  font-weight: 600;
  display: inline-block;
  background-image: linear-gradient(90deg, #6d7175 0%, #1a1a1a 22%, #008060 42%, #1a1a1a 62%, #6d7175 84%);
  background-size: 260% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  animation: shimmer 2.4s linear infinite !important;
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.scan-orbit {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid #008060;
  opacity: 0.35;
  animation: scanPulse 1.8s ease-out infinite !important;
}

.mini-spinner {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #ffffff;
  animation: spin 0.7s linear infinite !important;
}

/* ---------- hover / active states ---------- */

.q-option:hover {
  border-color: #c9cccf !important;
}

.btn:not(:disabled):hover {
  background: #006e52 !important;
  box-shadow: 0 6px 16px rgba(0, 128, 96, 0.25) !important;
}

.btn:not(:disabled):active {
  transform: scale(0.98) !important;
}

.scan-cta:hover:not(:disabled) {
  background: #006e52 !important;
}

.swatch-color:hover {
  transform: translateY(-2px);
  box-shadow:
    0 0 0 1px #c9cccf,
    0 6px 14px rgba(0, 0, 0, 0.1) !important;
}

.q-input:focus {
  outline: none;
  border-color: #008060 !important;
  box-shadow: 0 0 0 3px #e3f1ec !important;
}

/* Accessible focus ring */
button:focus-visible,
[tabindex]:focus-visible,
input:focus-visible {
  outline: 2px solid #008060;
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------- toggle switch knob ---------- */

.toggle-switch {
  position: relative;
}

.toggle-switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.2s ease;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
}

.toggle-switch.is-on::after {
  transform: translateX(16px);
}

/* Replays when swatch element is updated */
.swatch-color.is-updated {
  animation: swatchPop 0.5s ease;
}

/* ---------- responsive layout ---------- */

.toggle-grid,
.preset-grid {
  grid-template-columns: 1fr 1fr;
}

.panel {
  padding: 32px 30px;
}

@media (max-width: 560px) {
  .toggle-grid,
  .preset-grid {
    grid-template-columns: 1fr !important;
  }

  .panel {
    padding: 26px 20px !important;
  }

  .brand-swatches {
    flex-wrap: wrap !important;
  }

  .scan-card {
    flex-wrap: wrap !important;
  }

  .scan-cta {
    width: 100% !important;
    justify-content: center !important;
  }
}

/* ---------- end of onboarding.css ---------- */

import { useState, useEffect } from "react";
import type { CSSProperties, Dispatch, SetStateAction } from "react";
import type {
  BrandColorsType,
  OnboardingNewAnswersType,
  StageBrandColorType,
} from "../types";
import { ACCENT, DEFAULT_BRAND_COLORS, styles } from "../constants";

export type BrandColorPropsType = {
  stage: StageBrandColorType;
  answers: OnboardingNewAnswersType;
  setAnswers: Dispatch<SetStateAction<OnboardingNewAnswersType>>;
};

export function BrandColor({ stage, answers, setAnswers }: BrandColorPropsType) {
  const [scanning, setScanning] = useState(false);
  const [scanned, setScanned] = useState(false);
  const [popKey, setPopKey] = useState(0);

  const colors = (answers[stage.id] as BrandColorsType) || DEFAULT_BRAND_COLORS;

  useEffect(() => {
    if (!answers[stage.id]) setAnswers((prev) => ({ ...prev, [stage.id]: DEFAULT_BRAND_COLORS }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const updateColor = (key: keyof BrandColorsType, value: string) => {
    setAnswers((prev) => ({
      ...prev,
      [stage.id]: {
        ...((prev[stage.id] as BrandColorsType) || DEFAULT_BRAND_COLORS),
        [key]: value,
        source: "manual",
      },
    }));
  };

  const handleScan = () => {
    setScanning(true);
    setTimeout(() => {
      const detected: BrandColorsType = {
        primary: "#1F6F50",
        secondary: "#10241C",
        accent: "#E8B84B",
        background: "#F2F5F1",
      };
      setAnswers((prev) => ({ ...prev, [stage.id]: { ...detected, source: "scan" } }));
      setScanning(false);
      setScanned(true);
      setPopKey((k) => k + 1);
    }, 1500);
  };

  const order: [keyof BrandColorsType, string][] = [
    ["primary", "Primary"],
    ["secondary", "Secondary"],
    ["accent", "Accent"],
    ["background", "Background"],
  ];

  const swatchColorFn = styles.swatchColor as (bg: string) => CSSProperties;
  const brandPreviewFn = styles.brandPreview as (bg: string) => CSSProperties;
  const previewBtnFn = styles.previewBtn as (bg: string) => CSSProperties;
  const previewBadgeFn = styles.previewBadge as (bg: string) => CSSProperties;

  return (
    <>
      <div className="scan-card" style={styles.scanCard as CSSProperties}>
        <div style={styles.scanVisual as CSSProperties}>
          <div style={styles.scanOrbit as CSSProperties} />
          <div style={{ ...(styles.scanOrbit as CSSProperties), animationDelay: "0.6s" }} />
          <svg viewBox="0 0 24 24" fill="none" style={styles.scanStoreIcon as CSSProperties}>
            <path
              d="M3 9.5L4.5 4h15L21 9.5"
              stroke={ACCENT}
              strokeWidth="1.6"
              strokeLinejoin="round"
            />
            <path
              d="M3 9.5a2.5 2.5 0 0 0 5 0 2.5 2.5 0 0 0 5 0 2.5 2.5 0 0 0 5 0 2.5 2.5 0 0 0 5 0"
              stroke={ACCENT}
              strokeWidth="1.6"
              strokeLinejoin="round"
            />
            <path d="M5 9.5V20h14V9.5" stroke={ACCENT} strokeWidth="1.6" />
            <path d="M10 20v-6h4v6" stroke={ACCENT} strokeWidth="1.6" />
          </svg>
        </div>
        <div style={styles.scanCopy as CSSProperties}>
          <div style={styles.scanTitle as CSSProperties}>Scan your store for branding</div>
          <div style={styles.scanDesc as CSSProperties}>
            We'll analyze your storefront and match your colors automatically.
          </div>
        </div>
        <button
          type="button"
          className="scan-cta"
          style={styles.scanCta as CSSProperties}
          disabled={scanning}
          onClick={handleScan}
        >
          {scanning ? (
            <>
              <span style={styles.miniSpinner as CSSProperties} />
              <span>Scanning…</span>
            </>
          ) : (
            <span>{scanned ? "Scan again" : "Scan now"}</span>
          )}
        </button>
      </div>

      <p
        style={{
          ...(styles.scanStatus as CSSProperties),
          ...(scanned ? (styles.scanStatusVisible as CSSProperties) : {}),
        }}
      >
        <span>✓</span>
        <span>Colors updated from your store</span>
      </p>

      <div className="brand-swatches" style={styles.brandSwatches as CSSProperties}>
        {order.map(([key, label]) => (
          <div key={key} style={styles.swatchCard as CSSProperties}>
            <div
              key={`${key}-${popKey}`}
              className={`swatch-color${popKey > 0 ? " is-updated" : ""}`}
              style={swatchColorFn(colors[key] || "#000000")}
            >
              <input
                type="color"
                value={colors[key] || "#000000"}
                onChange={(e) => updateColor(key, e.target.value)}
                style={styles.colorInput as CSSProperties}
              />
              <div style={styles.swatchEdit as CSSProperties}>✎</div>
            </div>
            <span style={styles.swatchLabel as CSSProperties}>{label}</span>
            <span style={styles.swatchHex as CSSProperties}>{colors[key]}</span>
          </div>
        ))}
      </div>

      <div style={brandPreviewFn(colors.background || "#F6F6F7")}>
        <span style={styles.previewCaption as CSSProperties}>Live preview</span>
        <div style={styles.previewChipRow as CSSProperties}>
          <button type="button" style={previewBtnFn(colors.primary || "#008060")}>
            Add to cart
          </button>
          <span style={previewBadgeFn(colors.accent || "#E8B84B")}>Sale</span>
        </div>
      </div>
    </>
  );
}

import type { CSSProperties, Dispatch, SetStateAction } from "react";
import type { OnboardingNewAnswersType, StageChoiceQuestionsType } from "../types";
import { styles } from "../constants";

export type CheckIconPropsType = {
  selected?: boolean;
};

export function CheckIcon({ selected }: CheckIconPropsType) {
  return (
    <svg
      style={{
        ...(styles.checkIcon as CSSProperties),
        opacity: selected ? 1 : 0,
        transform: selected ? "scale(1)" : "scale(.5)",
      }}
      viewBox="0 0 16 16"
    >
      <path d="M3 8.5l3 3 7-7" style={styles.checkPath as CSSProperties} />
    </svg>
  );
}

export type ChoiceQuestionsPropsType = {
  stage: StageChoiceQuestionsType;
  answers: OnboardingNewAnswersType;
  setAnswers: Dispatch<SetStateAction<OnboardingNewAnswersType>>;
};

export function ChoiceQuestions({ stage, answers, setAnswers }: ChoiceQuestionsPropsType) {
  return (
    <>
      {stage.questions.map((q) => (
        <div key={q.id} style={styles.questionBlock as CSSProperties}>
          <div style={styles.qTitle as CSSProperties}>{q.question}</div>
          {q.subtitle && <div style={styles.qSub as CSSProperties}>{q.subtitle}</div>}

          {(q.type === "single" || q.type === "multi") && (
            <div
              style={styles.qOptions as CSSProperties}
              role={q.type === "multi" ? "group" : "radiogroup"}
            >
              {q.options?.map((opt) => {
                const isMulti = q.type === "multi";
                const currentVal = answers[q.id];
                const selected = isMulti
                  ? currentVal instanceof Set && currentVal.has(opt)
                  : currentVal === opt;

                return (
                  <button
                    key={opt}
                    type="button"
                    role={isMulti ? "checkbox" : "radio"}
                    aria-checked={selected}
                    className="q-option"
                    style={{
                      ...(styles.qOption as CSSProperties),
                      ...(selected ? (styles.qOptionSelected as CSSProperties) : {}),
                    }}
                    onClick={() => {
                      setAnswers((prev) => {
                        if (isMulti) {
                          const nextSet = new Set(prev[q.id] instanceof Set ? (prev[q.id] as Set<string>) : []);
                          if (nextSet.has(opt)) nextSet.delete(opt);
                          else nextSet.add(opt);
                          return { ...prev, [q.id]: nextSet };
                        }
                        return { ...prev, [q.id]: opt };
                      });
                    }}
                  >
                    <span
                      style={{
                        ...(styles.indicator as CSSProperties),
                        ...(isMulti ? (styles.indicatorSquare as CSSProperties) : {}),
                        ...(selected ? (styles.indicatorSelected as CSSProperties) : {}),
                      }}
                    >
                      <CheckIcon selected={selected} />
                    </span>
                    <span style={styles.optLabel as CSSProperties}>{opt}</span>
                  </button>
                );
              })}
            </div>
          )}

          {q.type === "input" && (
            <div style={styles.qInputWrap as CSSProperties}>
              <span style={styles.qInputPrefix as CSSProperties}>{q.prefix}</span>
              <input
                type="text"
                inputMode="decimal"
                autoComplete="off"
                placeholder={q.placeholder}
                value={(answers[q.id] as string) || ""}
                className="q-input"
                style={styles.qInput as CSSProperties}
                onChange={(e) => setAnswers((prev) => ({ ...prev, [q.id]: e.target.value }))}
              />
            </div>
          )}
        </div>
      ))}
    </>
  );
}

import { useState, useEffect } from "react";
import type { CSSProperties } from "react";
import { styles } from "../constants";

export type CompleteStagePropsType = {
  onRestart?: () => void;
  onGoToDashboard?: () => void;
};

export function CompleteStage({ onRestart, onGoToDashboard }: CompleteStagePropsType) {
  const [drawn, setDrawn] = useState(false);

  useEffect(() => {
    const raf = requestAnimationFrame(() => requestAnimationFrame(() => setDrawn(true)));
    return () => cancelAnimationFrame(raf);
  }, []);

  const handleAction = () => {
    if (onGoToDashboard) {
      onGoToDashboard();
    } else if (onRestart) {
      onRestart();
    }
  };

  return (
    <>
      <div className="panel" style={styles.panel as CSSProperties}>
        <div style={styles.complete as CSSProperties}>
          <div style={styles.checkWrap as CSSProperties}>
            <div style={styles.checkCircle as CSSProperties}>
              <svg viewBox="0 0 24 24" style={styles.checkSvg as CSSProperties}>
                <path
                  d="M4 12l6 6 10-12"
                  style={{
                    ...(styles.checkPathComplete as CSSProperties),
                    strokeDashoffset: drawn ? 0 : 24,
                    transition: "stroke-dashoffset .5s ease .2s",
                  }}
                />
              </svg>
            </div>
          </div>
          <h2 style={styles.completeH2 as CSSProperties}>You&apos;re all set</h2>
          <p style={styles.completeP as CSSProperties}>Your revenue tools are configured and ready to go.</p>
        </div>
      </div>
      <button
        type="button"
        className="btn"
        style={styles.btn as CSSProperties}
        onClick={handleAction}
      >
        Enter dashboard
      </button>
    </>
  );
}

import { useState, useEffect } from "react";
import type { CSSProperties } from "react";
import { styles } from "../constants";
import { Spinner, Text } from "@xco-agency/corex-ui";

export type ProcessingStagePropsType = {
  texts: string[];
  onDone: () => void;
};

export function ProcessingStage({ texts, onDone }: ProcessingStagePropsType) {
  const [textIndex, setTextIndex] = useState(0);
  const [changing, setChanging] = useState(false);

  useEffect(() => {
    const textTimer = setInterval(() => {
      setChanging(true);
      setTimeout(() => {
        setTextIndex((i) => (i + 1) % texts.length);
        setChanging(false);
      }, 200);
    }, 2000);

    const apiTimer = setTimeout(
      () => {
        onDone();
      },
      8600 + Math.random() * 400,
    );

    return () => {
      clearInterval(textTimer);
      clearTimeout(apiTimer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div style={styles.processing as CSSProperties}>
      <span style={{ scale: "1.5" }}>
        <Spinner />
      </span>
      <span
        className="processing-text"
        style={{
          ...(styles.processingText as CSSProperties),
          WebkitTextFillColor: "transparent",
          opacity: changing ? 0 : 1,
          transform: changing ? "translateY(6px)" : "translateY(0)",
        }}
      >
        <Text variant="headingXl" lineClamp={1} heading>
          {texts[textIndex]}
        </Text>
      </span>
    </div>
  );
}

import { useEffect } from "react";
import type { CSSProperties, Dispatch, SetStateAction } from "react";
import type {
  CartPresetIdType,
  OnboardingNewAnswersType,
  StageStylePresetType,
} from "../types";
import { CART_PRESET_STYLES, styles } from "../constants";

export type CartPreviewPropsType = {
  presetId: CartPresetIdType;
};

export function CartPreview({ presetId }: CartPreviewPropsType) {
  const p = CART_PRESET_STYLES[presetId] || CART_PRESET_STYLES.minimal;
  const items = [{ price: "$28" }, { price: "$42" }];

  return (
    <div style={{ ...(styles.cartPreview as CSSProperties), ...(p.container as CSSProperties) }}>
      <div style={{ ...(styles.cpHeader as CSSProperties), ...(p.header as CSSProperties) }}>
        <span style={{ ...(styles.cpTitle as CSSProperties), ...(p.title as CSSProperties) }}>Cart (2)</span>
        <span style={{ ...(styles.cpClose as CSSProperties), ...(p.title as CSSProperties) }}>×</span>
      </div>

      {items.map((item, i) => (
        <div key={i} style={{ ...(styles.cpItem as CSSProperties), ...(p.item as CSSProperties) }}>
          <div style={{ ...(styles.cpThumb as CSSProperties), ...(p.thumb as CSSProperties) }} />
          <div style={styles.cpInfo as CSSProperties}>
            <div style={styles.cpName as CSSProperties} />
            <div style={styles.cpVariant as CSSProperties} />
          </div>
          <div style={styles.cpRight as CSSProperties}>
            <div style={{ ...(styles.cpPrice as CSSProperties), ...(p.price as CSSProperties) }}>{item.price}</div>
            <div style={{ ...(styles.cpQty as CSSProperties), ...(p.qty as CSSProperties) }}>
              <span>−</span>
              <span>1</span>
              <span>+</span>
            </div>
          </div>
        </div>
      ))}

      <div style={styles.cpFooter as CSSProperties}>
        <div style={styles.cpSubtotal as CSSProperties}>
          <span>Subtotal</span>
          <span>$70</span>
        </div>
        <div style={{ ...(styles.cpCta as CSSProperties), ...(p.cta as CSSProperties) }}>Checkout</div>
      </div>
    </div>
  );
}

export type StylePresetPropsType = {
  stage: StageStylePresetType;
  answers: OnboardingNewAnswersType;
  setAnswers: Dispatch<SetStateAction<OnboardingNewAnswersType>>;
};

export function StylePreset({ stage, answers, setAnswers }: StylePresetPropsType) {
  const selected = (answers[stage.id] as CartPresetIdType) || stage.default;

  useEffect(() => {
    if (!answers[stage.id]) setAnswers((prev) => ({ ...prev, [stage.id]: stage.default }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="preset-grid" style={styles.presetGrid as CSSProperties}>
      {stage.options.map((opt) => {
        const isSelected = selected === opt.id;
        return (
          <div
            key={opt.id}
            role="radio"
            aria-checked={isSelected}
            tabIndex={0}
            style={{
              ...(styles.presetCard as CSSProperties),
              ...(isSelected ? (styles.presetCardSelected as CSSProperties) : {}),
            }}
            onClick={() => setAnswers((prev) => ({ ...prev, [stage.id]: opt.id }))}
            onKeyDown={(e) => {
              if (e.key === " " || e.key === "Enter") {
                e.preventDefault();
                setAnswers((prev) => ({ ...prev, [stage.id]: opt.id }));
              }
            }}
          >
            <CartPreview presetId={opt.id} />
            <div style={styles.presetLabel as CSSProperties}>{opt.label}</div>
          </div>
        );
      })}
    </div>
  );
}

import { useEffect } from "react";
import type { CSSProperties, Dispatch, SetStateAction } from "react";
import type { OnboardingNewAnswersType, StageToggleGridType } from "../types";
import { styles } from "../constants";

export type ToggleGridPropsType = {
  stage: StageToggleGridType;
  answers: OnboardingNewAnswersType;
  setAnswers: Dispatch<SetStateAction<OnboardingNewAnswersType>>;
};

export function ToggleGrid({ stage, answers, setAnswers }: ToggleGridPropsType) {
  const selected =
    answers[stage.id] instanceof Set
      ? (answers[stage.id] as Set<string>)
      : new Set(stage.options.filter((o) => o.default).map((o) => o.id));

  useEffect(() => {
    if (!(answers[stage.id] instanceof Set)) {
      setAnswers((prev) => ({ ...prev, [stage.id]: selected }));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const toggle = (id: string) => {
    setAnswers((prev) => {
      const current = prev[stage.id];
      const next = new Set(current instanceof Set ? (current as Set<string>) : []);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, [stage.id]: next };
    });
  };

  return (
    <>
      <div className="toggle-grid" style={styles.toggleGrid as CSSProperties}>
        {stage.options.map((opt) => {
          const isOn = selected.has(opt.id);
          return (
            <div
              key={opt.id}
              role="switch"
              aria-checked={isOn}
              tabIndex={0}
              style={{
                ...(styles.toggleCard as CSSProperties),
                ...(isOn ? (styles.toggleCardOn as CSSProperties) : {}),
              }}
              onClick={() => toggle(opt.id)}
              onKeyDown={(e) => {
                if (e.key === " " || e.key === "Enter") {
                  e.preventDefault();
                  toggle(opt.id);
                }
              }}
            >
              {opt.badge && <span style={styles.badge as CSSProperties}>{opt.badge}</span>}
              <div
                style={{
                  ...(styles.toggleIconWrap as CSSProperties),
                  ...(isOn ? (styles.toggleIconWrapOn as CSSProperties) : {}),
                }}
              >
                {opt.icon}
              </div>
              <div style={styles.toggleTitle as CSSProperties}>{opt.title}</div>
              <div style={styles.toggleDesc as CSSProperties}>{opt.desc}</div>
              <div
                className={`toggle-switch${isOn ? " is-on" : ""}`}
                style={{
                  ...(styles.toggleSwitch as CSSProperties),
                  ...(isOn ? (styles.toggleSwitchOn as CSSProperties) : {}),
                }}
              />
            </div>
          );
        })}
      </div>
      <p style={styles.hintNote as CSSProperties}>You can add or remove these anytime from your dashboard.</p>
    </>
  );
}

